terms.medium_def:
A location first mentioned at 1Sa.23.15; 
only referred to as Horesh (חֹ֫רֶשׁ). §
This name means wood, forest

A man living at the time of Divided Monarchy, first mentioned at 2Ki.25.23; 
referred to as Jezaniah (יְזַנְיָה), or Jezaniah or Jaazaniah (יַאֲזַנְיָ֫הוּ), or Azariah (עֲזַרְיָה); 
a son of Hoshaiah.

A man from the tribe of Gad living at the time of Egypt and Wilderness, first mentioned at Gen.46.16; 
referred to as Ezbon (אֶצְבּוֹן), or Ozni (אׇזְנִי), or Oznite (אׇזְנִי); 
son of Gad; 
a brother of Ziphion, Haggi, Shuni, Eri, Arod and Areli. § son of Gad

A man from the tribe of Gad living at the time of Egypt and Wilderness, first mentioned at Gen.46.16; 
referred to as Ezbon (אֶצְבּוֹן), or Ozni (אׇזְנִי), or Oznite (אׇזְנִי); 
son of Gad; 
a brother of Ziphion, Haggi, Shuni, Eri, Arod and Areli. § pertaining to Ozni and his descendants

A man living at the time of Exile and Return, only mentioned at Neh.10.9; 
only referred to as Azaniah (אֲזַנְיָ֫הוּ); 
father of Jeshua. § the father of Jeshua, a Levite

A man living at the time of Divided Monarchy, only mentioned at Jer.35.3; 
only referred to as Jaazaniah (יַאֲזַנְיָ֫הוּ); 
a son of Jeremiah.

A man living at the time of Exile and Return, only mentioned at Ezk.8.11; 
only referred to as Jaazaniah (יַאֲזַנְיָ֫הוּ); 
a son of Shaphan.

A man living at the time of Exile and Return, only mentioned at Ezk.11.1; 
only referred to as Jaazaniah (יַאֲזַנְיָ֫הוּ); 
a son of Azzur.

A man living at the time of Divided Monarchy, first mentioned at 2Ki.25.23; 
referred to as Jezaniah (יְזַנְיָה), or Jezaniah or Jaazaniah (יַאֲזַנְיָ֫הוּ), or Azariah (עֲזַרְיָה); 
a son of Hoshaiah. § son of Hoshaiah the Maachathite and one of the captains who escaped from Jerusalem during the last siege of the Babylonians; one of the first to return to Gedaliah at Mizpah where he took a prominent part after the assassination of Gedaliah

Jacob's son who founded the tribe of Simeon living at the time of the Patriarchs, first mentioned at Gen.29.33; 
referred to as Simeon or Simeonite (שִׁמְעוֹן), or Simeon or Simeonite (שִׁמְעֹנִי), or Simeon (Συμεών); 
son of Israel and Leah; 
a brother of Reuben, Levi, Judah, Issachar, Zebulun and Dinah; 
half-brother of: Dan, Naphtali, Gad, Asher, Joseph and Benjamin; 
husband of Canaanite_woman; 
father of Jemuel, Jamin, Ohad, Jachin, Zerah and Shaul.

An adversary of Jeremiah living at the time of Divided Monarchy, first mentioned at 2Ki.25.23; 
only referred to as Ishmael (יִשְׁמָעֵאל); 
a son of Nethaniah.

Abraham's son living at the time of the Patriarchs, first mentioned at Gen.16.11; 
referred to as Ishmael (יִשְׁמָעֵאל), or Ishmaelite (KJV= Ishmeelite) or Ishmaelite (יִשְׁמְעֵאלִי), or Ishmaelite (יִשְׂרְאֵלִי); 
a son of Abraham and Hagar; 
half-brother of: Isaac, Zimran, Jokshan, Medan, Midian, Ishbak and Shuah; 
father of Nebaioth, Kedar, Adbeel, Mibsam, Mishma, Dumah, Massa, Hadad, Tema, Jetur, Naphish, Kedemah and Mahalath.

David's adversary living at the time of United Monarchy, first mentioned at 2Sa.16.5; 
only referred to as Shimei (שִׁמְעִי); 
a son of Gera.

Abraham's son living at the time of the Patriarchs, first mentioned at Gen.16.11; 
referred to as Ishmael (יִשְׁמָעֵאל), or Ishmaelite (KJV= Ishmeelite) or Ishmaelite (יִשְׁמְעֵאלִי), or Ishmaelite (יִשְׂרְאֵלִי); 
a son of Abraham and Hagar; 
half-brother of: Isaac, Zimran, Jokshan, Medan, Midian, Ishbak and Shuah; 
father of Nebaioth, Kedar, Adbeel, Mibsam, Mishma, Dumah, Massa, Hadad, Tema, Jetur, Naphish, Kedemah and Mahalath. § Ishmaelite , of Ishmael "God will hear"
a descendant of Ishmael

A man from the tribe of Levi living at the time of Egypt and Wilderness, first mentioned at Exo.6.17; 
referred to as Shimei or Shimei (KJV= Shimi) (שִׁמְעִי), or Shimeite (KJV= Shimite) or Shimeite (KJV, NIV= Shimei) (שִׁמְעִי); 
son of Gershon; 
a brother of Libni; 
father of Jahath, Zizah, Jeush and Beriah.

Jacob's son who founded the tribe of Simeon living at the time of the Patriarchs, first mentioned at Gen.29.33; 
referred to as Simeon or Simeonite (שִׁמְעוֹן), or Simeon or Simeonite (שִׁמְעֹנִי), or Simeon (Συμεών); 
son of Israel and Leah; 
a brother of Reuben, Levi, Judah, Issachar, Zebulun and Dinah; 
half-brother of: Dan, Naphtali, Gad, Asher, Joseph and Benjamin; 
husband of Canaanite_woman; 
father of Jemuel, Jamin, Ohad, Jachin, Zerah and Shaul. § Simeonites, of Simeon "harkening"
descendants of Simeon

David's brother from the tribe of Judah living at the time of United Monarchy, first mentioned at 1Sa.16.9; 
referred to as Shimeah (שִׁמְעָה), or Shimei (=Ketiv. Qere, NIV= Shimeah, KJV= Shimea) (שִׁמְעִי), or Shammah (שַׁמָּה), or Shimea (שִׁמְעָא); 
son of Jesse; 
a brother of David, Eliab, Abinadab, Nethanel, Raddai, Ozem, Zeruiah, Abigail(?) and Elihu; 
father of Jonadab.

A man from the tribe of Levi living at the time of United Monarchy, first mentioned at 1Ch.26.4; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
son of Obed-edom; 
a brother of Jehozabad, Joah, Sachar, Nethanel, Ammiel, Issachar and Peullethai; 
father of Othni, Rephael, Obed, Elzabad, Elihu and Semachiah.

A man from the tribe of Benjamin living at the time of Divided Monarchy, first mentioned at 1Ch.8.38; 
only referred to as Ishmael (יִשְׁמָעֵאל); 
son of Azel; 
a brother of Azrikam, Bocheru, Sheariah, Obadiah and Hanan.

A man of the Arabs living at the time of the Patriarchs, first mentioned at Gen.25.14; 
only referred to as Mishma (מִשְׁמָע); 
son of Ishmael; 
a brother of Nebaioth, Kedar, Adbeel, Mibsam, Dumah, Massa, Hadad, Tema, Jetur, Naphish, Kedemah and Mahalath.

A man from the tribe of Simeon living at the time of Divided Monarchy, first mentioned at 1Ch.4.25; 
only referred to as Mishma (מִשְׁמָע); 
a son of Mibsam; 
father of Hammuel.

David's son from the tribe of Judah living at the time of United Monarchy, first mentioned at 2Sa.5.14; 
referred to as Shammua or Shammua (שַׁמּוּעַ), or Shimea (שִׁמְעָא, שִׁמְעָה); 
son of David and Bathsheba; 
a brother of Shobab, Nathan and Solomon; 
half-brother of: Amnon, Chileab, Absalom, Adonijah, Shephatiah, Ithream, Ibhar, Elishua, Nepheg, Japhia, Elishama, Eliada, Eliphelet, Tamar, Elpelet, Nogah and Jerimoth.

A man from the tribe of Judah living at the time of Divided Monarchy, first mentioned at 1Ch.2.43; 
only referred to as Shema (שֶׁ֫מַע); 
son of Hebron; 
a brother of Korah, Tappuah and Rekem; 
father of Raham.

David's brother from the tribe of Judah living at the time of United Monarchy, first mentioned at 1Sa.16.9; 
referred to as Shimeah (שִׁמְעָה), or Shimei (=Ketiv. Qere, NIV= Shimeah, KJV= Shimea) (שִׁמְעִי), or Shammah (שַׁמָּה), or Shimea (שִׁמְעָא); 
son of Jesse; 
a brother of David, Eliab, Abinadab, Nethanel, Raddai, Ozem, Zeruiah, Abigail(?) and Elihu; 
father of Jonadab.

A man living at the time of United Monarchy, first mentioned at 1Ki.1.8; 
only referred to as Shimei (שִׁמְעִי); 
a son of Ela.

A man from the tribe of Simeon living at the time of Divided Monarchy, first mentioned at 1Ch.4.26; 
only referred to as Shimei (שִׁמְעִי); 
a son of Zaccur.

A man living at the time of Divided Monarchy, first mentioned at 2Ch.31.12; 
only referred to as Shimei (שִׁמְעִי); 
a brother of Conaniah.

A man from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.6.39; 
only referred to as Shimei (שִׁמְעִי); 
a son of Jehiel; 
father of Zimmah, Shelomith, Haziel, Haran.

A man from the tribe of Levi living at the time of Egypt and Wilderness, first mentioned at Exo.6.17; 
referred to as Shimei or Shimei (KJV= Shimi) (שִׁמְעִי), or Shimeite (KJV= Shimite) or Shimeite (KJV, NIV= Shimei) (שִׁמְעִי); 
son of Gershon; 
a brother of Libni; 
father of Jahath, Zizah, Jeush and Beriah. § Shimites, of Shimei "renowned"
descendants of Shimei or Shimi

A man from the tribe of Levi living at the time of Exile and Return, first mentioned at 1Ch.9.14; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
a son of Hasshub.

A woman of the Ammonites living at the time of Divided Monarchy, first mentioned at 2Ki.12.21; 
only referred to as Shimeath (שִׁמְעָת); 
mother of Jozacar. § an Ammonitess, mother of Jozachar or Zabad, one of the assassins of king Joash of Judah

A man living at the time of Divided Monarchy, only mentioned at 2Ch.19.11; 
only referred to as Ishmael (יִשְׁמָעֵאל); 
father of Zebadiah.

A man living at the time of Divided Monarchy, only mentioned at 2Ch.23.1; 
only referred to as Ishmael (יִשְׁמָעֵאל); 
a son of Jehohanan.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.27.19; 
only referred to as Ishmaiah (יִשְׁמַעְיָ֫הוּ); 
a son of Obadiah.

A man living at the time of Egypt and Wilderness, only mentioned at Num.13.4; 
only referred to as Shammua (שַׁמּוּעַ); 
a son of Zaccur.

A man from the tribe of Levi living at the time of Exile and Return, first mentioned at 1Ch.9.16; 
referred to as Shemaiah (שְׁמַעְיָ֫הוּ), or Shammua (שַׁמּוּעַ); 
a son of Galal; 
father of Obadiah.

A man from the tribe of Reuben living at the time of Divided Monarchy, only mentioned at 1Ch.5.8; 
only referred to as Shema (שֶׁ֫מַע); 
a son of Joel; 
father of Azaz.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.13; 
only referred to as Shema (שֶׁ֫מַע); 
son of Elpaal; 
a brother of Eber, Misham, Shemed, Beriah, Zebadiah, Meshullam, Hizki, Heber, Ishmerai, Izliah and Jobab.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.11.44; 
only referred to as Shama (שָׁמָע); 
son of Hotham; 
a brother of Jeiel. § son of Hotham the Aroerite, brother of Jeiel, both listed as mighty warriors of David

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 1Ch.6.30; 
only referred to as Shimea (שִׁמְעָא, שִׁמְעָה); 
a son of Uzzah; 
father of Haggiah.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 1Ch.6.39; 
only referred to as Shimea (שִׁמְעָא, שִׁמְעָה); 
a son of Michael; 
father of Berechiah.

David's son from the tribe of Judah living at the time of United Monarchy, first mentioned at 2Sa.5.14; 
referred to as Shammua or Shammua (שַׁמּוּעַ), or Shimea (שִׁמְעָא, שִׁמְעָה); 
son of David and Bathsheba; 
a brother of Shobab, Nathan and Solomon; 
half-brother of: Amnon, Chileab, Absalom, Adonijah, Shephatiah, Ithream, Ibhar, Elishua, Nepheg, Japhia, Elishama, Eliada, Eliphelet, Tamar, Elpelet, Nogah and Jerimoth.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.12.3; 
only referred to as Shemaah (שְׁמָעָה); 
father of Ahiezer, Joash. § a Benjamite, the Gibeathite, father of Ahiezer and Joash, both mighty warriors of David who joined him at Ziklag

A man from the tribe of Judah living at the time of Divided Monarchy, only mentioned at 1Ch.3.19; 
only referred to as Shimei (שִׁמְעִי); 
son of Pedaiah; 
a brother of Zerubbabel.

A man from the tribe of Reuben living at the time of Divided Monarchy, only mentioned at 1Ch.5.4; 
only referred to as Shimei (שִׁמְעִי); 
a son of Gog; 
father of Micah.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 1Ch.6.29; 
only referred to as Shimei (שִׁמְעִי); 
a son of Libni; 
father of Uzzah.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.21; 
only referred to as Shimei (שִׁמְעִי); 
father of Jakim, Zichri, Zabdi, Elienai, Zillethai, Eliel, Adaiah, Beraiah and Shimrath.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 2Ch.29.14; 
only referred to as Shimei (שִׁמְעִי); 
son of Heman; 
a brother of Jehuel.

A man living at the time of Exile and Return, only mentioned at Est.2.5; 
only referred to as Shimei (שִׁמְעִי); 
a son of Kish; 
father of Jair.

A Singer from the tribe of Levi living at the time of United Monarchy, first mentioned at 2Sa.6.10; 
referred to as Obed-edom (עֹבֵד אֱדוֹם), or Shimei (שִׁמְעִי); 
son of Jeduthun; 
a brother of Mattithiah, Gedaliah, Zeri, Jeshaiah and Hashabiah; 
father of Shemaiah, Jehozabad, Joah, Sachar, Nethanel, Ammiel, Issachar and Peullethai.

A man from the tribe of Judah living at the time of Divided Monarchy, first mentioned at 1Ch.3.22; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
a son of Shecaniah; 
father of Hattush, Igal, Bariah, Neariah and Shaphat.

A man from the tribe of Simeon(?) living at the time of Divided Monarchy, only mentioned at 1Ch.4.37; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
father of Shimri.

A man from the tribe of Reuben living at the time of Divided Monarchy, only mentioned at 1Ch.5.4; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
a son of Joel; 
father of Gog.

A man from the tribe of Levi living at the time of Exile and Return, first mentioned at 1Ch.9.16; 
referred to as Shemaiah (שְׁמַעְיָ֫הוּ), or Shammua (שַׁמּוּעַ); 
a son of Galal; 
father of Obadiah.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.24.6; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
a son of Nethanel.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 2Ch.29.14; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
son of Jeduthun; 
a brother of Uzziel.

A man living at the time of Exile and Return, only mentioned at Neh.3.29; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
a son of Shecaniah.

A man living at the time of Exile and Return, only mentioned at Neh.6.10; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
a son of Delaiah.

A priest living at the time of Exile and Return, only mentioned at Neh.12.35; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
son of Mattaniah; 
a brother of Hashabiah; 
father of Jonathan.

A man living at the time of Exile and Return, only mentioned at Neh.12.36; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
son of Jonathan; 
a brother of Zechariah, Azarel, Milalai, Gilalai, Maai, Nethanel, Judah and Hanani.

A man living at the time of Divided Monarchy, only mentioned at Jer.26.20; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
father of Uriah.

A man living at the time of Divided Monarchy, only mentioned at Jer.36.12; 
only referred to as Shemaiah (שְׁמַעְיָ֫הוּ); 
father of Delaiah.

David's brother from the tribe of Judah living at the time of United Monarchy, first mentioned at 1Sa.16.9; 
referred to as Shimeah (שִׁמְעָה), or Shimei (=Ketiv. Qere, NIV= Shimeah, KJV= Shimea) (שִׁמְעִי), or Shammah (שַׁמָּה), or Shimea (שִׁמְעָא); 
son of Jesse; 
a brother of David, Eliab, Abinadab, Nethanel, Raddai, Ozem, Zeruiah, Abigail(?) and Elihu; 
father of Jonadab.

A man living at the time of Exile and Return, only mentioned at Neh.11.7; 
only referred to as Kolaiah (קוֹלָיָה); 
a son of Maaseiah; 
father of Pedaiah.

A man living at the time of Divided Monarchy, only mentioned at Jer.29.21; 
only referred to as Kolaiah (קוֹלָיָה); 
father of Ahab.
